--
-- Table structure for table `marks`
--

DROP TABLE IF EXISTS `marks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `marks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint unsigned NOT NULL,
  `subject_id` bigint unsigned NOT NULL,
  `class_id` bigint unsigned NOT NULL,
  `term_id` bigint unsigned NOT NULL,
  `academic_year_id` bigint unsigned NOT NULL,
  `school_id` bigint unsigned NOT NULL,
  `exam_id` bigint unsigned DEFAULT NULL,
  `activity_id` bigint unsigned DEFAULT NULL,
  `strand_id` bigint unsigned DEFAULT NULL,
  `sub_strand_id` bigint unsigned DEFAULT NULL,
  `activity_component_id` bigint unsigned DEFAULT NULL,
  `assessment_type` enum('formative','summative') COLLATE utf8mb4_unicode_ci DEFAULT 'formative',
  `assessment_method` enum('written','oral','practical','observation','portfolio','project') COLLATE utf8mb4_unicode_ci DEFAULT 'written',
  `marks` decimal(6,2) DEFAULT NULL COMMENT 'Raw marks (0-100 scale)',
  `max_marks` decimal(6,2) DEFAULT '100.00',
  `percentage` decimal(5,2) GENERATED ALWAYS AS ((case when (`max_marks` > 0) then ((`marks` / `max_marks`) * 100) else NULL end)) STORED,
  `performance_level` enum('elementary','basic','satisfactory','outstanding','exceptional') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `race_relevance` int DEFAULT NULL,
  `race_accuracy` int DEFAULT NULL,
  `race_coherence` int DEFAULT NULL,
  `race_excellence` int DEFAULT NULL,
  `grade` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `points` decimal(3,1) DEFAULT NULL,
  `teacher_id` bigint unsigned DEFAULT NULL,
  `teacher_comment` text COLLATE utf8mb4_unicode_ci,
  `is_absent` tinyint(1) DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `recorded_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `race_average` decimal(3,2) GENERATED ALWAYS AS ((((((coalesce(`race_relevance`,0) + coalesce(`race_accuracy`,0)) + coalesce(`race_coherence`,0)) + coalesce(`race_excellence`,0)) / 10) * 3.0)) STORED,
