--

DROP TABLE IF EXISTS `payroll_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payroll_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint unsigned DEFAULT NULL,
  `teacher_id` bigint unsigned DEFAULT NULL,
  `academic_year` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Format: YYYY-YYYY',
  `month` enum('January','February','March','April','May','June','July','August','September','October','November','December') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payment_date` date NOT NULL,
  `basic_salary` decimal(10,2) NOT NULL,
  `housing_allowance` decimal(10,2) DEFAULT '0.00',
  `transport_allowance` decimal(10,2) DEFAULT '0.00',
  `medical_allowance` decimal(10,2) DEFAULT '0.00',
  `other_allowances` decimal(10,2) DEFAULT '0.00',
  `gross_salary` decimal(10,2) GENERATED ALWAYS AS (((((`basic_salary` + `housing_allowance`) + `transport_allowance`) + `medical_allowance`) + `other_allowances`)) STORED,
  `paye_amount` decimal(10,2) DEFAULT '0.00',
  `nssf_employee_amount` decimal(10,2) DEFAULT '0.00',
  `nhif_amount` decimal(10,2) DEFAULT '0.00',
  `loan_deduction` decimal(10,2) DEFAULT '0.00',
  `other_deductions` decimal(10,2) DEFAULT '0.00',
  `total_deductions` decimal(10,2) GENERATED ALWAYS AS (((((`paye_amount` + `nssf_employee_amount`) + `nhif_amount`) + `loan_deduction`) + `other_deductions`)) STORED,
  `net_pay` decimal(10,2) GENERATED ALWAYS AS ((`gross_salary` - `total_deductions`)) STORED,
  `payment_method` enum('Bank Transfer','Cash','Cheque','Mobile Money') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Bank Transfer',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_ref` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Pending','Processed','Paid','Failed','Reversed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Pending',
  `approval_status` enum('Pending','Approved','Rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Pending',
  `approved_by_teacher_id` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `processed_by_teacher_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_teacher_month` (`teacher_id`,`month`,`academic_year`),
  KEY `idx_school_month` (`school_id`,`month`,`academic_year`),
  KEY `idx_status` (`status`),
  KEY `idx_payment_date` (`payment_date`),
  KEY `idx_approval_status` (`approval_status`),
