INSERT INTO `report_comments` VALUES (3,3,1,1,1,1,1,'class_teacher','David Johnson demonstrates extraordinary competency, applying skills innovatively and creatively in real-life situations. He consistently show exceptional understanding, independently solving complex problems and serving as a role model for peers.',1,'2025-11-29 09:37:36','Exceptional'),(4,3,1,1,1,1,1,'head_teacher','David Johnson exhibits mastery and leadership in applying knowledge within practical contexts. He independently plan, innovate, and execute complex tasks, consistently producing high-quality work. He is a good student',1,'2025-11-29 18:01:48','Outstanding'),(5,1,3,3,2,1,10,'head_teacher','He has demonstrated basics',1,'2026-02-10 15:47:48','Satisfactory');
