DROP TABLE IF EXISTS `salary_increments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `salary_increments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `staff_id` bigint unsigned DEFAULT NULL,
  `old_basic_salary` decimal(10,2) NOT NULL,
  `new_basic_salary` decimal(10,2) NOT NULL,
  `increment_amount` decimal(10,2) GENERATED ALWAYS AS ((`new_basic_salary` - `old_basic_salary`)) STORED,
  `increment_percentage` decimal(5,2) GENERATED ALWAYS AS ((case when (`old_basic_salary` > 0) then round(((`increment_amount` / `old_basic_salary`) * 100),2) else NULL end)) STORED,
  `reason` enum('Annual Review','Promotion','Performance','Correction','Other') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `effective_date` date NOT NULL,
  `approved_by_teacher_id` bigint unsigned DEFAULT NULL,
  `status` enum('Pending','Approved','Applied') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Approved',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_staff_id` (`staff_id`),
  KEY `idx_effective_date` (`effective_date`),
  KEY `idx_status` (`status`),
  KEY `approved_by_teacher_id` (`approved_by_teacher_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
